import { createAudioPlayer, type AudioPlayer } from "expo-audio";

/**
 * Board sounds, from assets/sounds (generated by scripts/make-sounds.py, the
 * same files as the web app's).
 *
 * One player per sound, created on first use and kept: stepping quickly
 * through a game plays a sound per move, and creating a player each time
 * would lag behind the board. A sound that is still playing restarts.
 */
export type SoundKind = "move" | "capture" | "castle" | "check" | "end";

const SOURCES: Record<SoundKind, number> = {
  move: require("../../assets/sounds/move.wav"),
  capture: require("../../assets/sounds/capture.wav"),
  castle: require("../../assets/sounds/castle.wav"),
  check: require("../../assets/sounds/check.wav"),
  end: require("../../assets/sounds/end.wav"),
};

const players: Partial<Record<SoundKind, AudioPlayer>> = {};

/** The sound a move makes, from its SAN: "O-O", "exd5", "Qh5+", "Qxf7#". */
export function soundFor(san: string, isLastMoveOfFinishedGame = false): SoundKind {
  if (san.endsWith("#") || isLastMoveOfFinishedGame) return "end";
  if (san.endsWith("+")) return "check";
  if (san.startsWith("O-O")) return "castle";
  if (san.includes("x")) return "capture";
  return "move";
}

export function playSound(kind: SoundKind) {
  try {
    const player = (players[kind] ??= createAudioPlayer(SOURCES[kind]));
    void player.seekTo(0);
    player.play();
  } catch {
    // No audio on this device: the board works the same without it.
  }
}
